CREATE TABLE IF NOT EXISTS risk_assessments (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',subject_component TEXT NOT NULL,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,title TEXT NOT NULL,owner_type TEXT NOT NULL DEFAULT 'user',owner_id TEXT NOT NULL,review_due_at TEXT,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','in_review','approved','rejected','withdrawn')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS risk_items (id INTEGER PRIMARY KEY AUTOINCREMENT,assessment_id INTEGER NOT NULL,hazard TEXT NOT NULL,people_at_risk TEXT NOT NULL,likelihood INTEGER NOT NULL CHECK(likelihood BETWEEN 1 AND 5),impact INTEGER NOT NULL CHECK(impact BETWEEN 1 AND 5),controls TEXT NOT NULL,residual_likelihood INTEGER NOT NULL CHECK(residual_likelihood BETWEEN 1 AND 5),residual_impact INTEGER NOT NULL CHECK(residual_impact BETWEEN 1 AND 5),action_owner_type TEXT,action_owner_id TEXT,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','controlled','withdrawn')),created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(assessment_id) REFERENCES risk_assessments(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_risk_subject ON risk_assessments(app_id,subject_component,subject_type,subject_id,status);CREATE INDEX IF NOT EXISTS idx_risk_items ON risk_items(assessment_id,status);
